import type {ActionContext,ChooseOptions,ChooseResult} from './sdk/api';
export type JsonKind = 'object'|'array'|'string'|'number'|'boolean'|'null';
export type Format = 'compact'|'pretty';
export type JsonMode = 'inspect'|'send'|'choose-send';
export type EffectState = 'not_started'|'unknown';
export type JsonMethod = 'script.parameters'|'ui.choose'|'keyboard.text';
export type JsonErrorCode = 'invalid_input'|'invalid_json'|'json_limit'|'json_duplicate_key'|'json_output_too_large'|'json_path_type'|'json_path_missing'|'invalid_response'|'ui_unavailable'|'ui_busy'|'ui_error'|'desktop_unavailable'|'native_bridge_unavailable'|'target_changed'|'target_unavailable'|'cancelled'|'timeout'|'input_failed'|'json_text_failed'|'json_selection_failed';
export type FaultInfo = {code?:unknown;effectState?:unknown};
export type JsonActionFault = Error & {code:JsonErrorCode;method:JsonMethod;effectState:EffectState};
export type NodeContext = Omit<ActionContext,'input'> & {readonly input:unknown};
export type SyncContext = Omit<ScriptContext,'input'> & {readonly input:unknown};
export type SubmitReceipt = {submitted:true};
export type SharedContext = {ui?:{choose(options:ChooseOptions):ChooseResult|Promise<ChooseResult>};desktop?:{sendText(text:string):SubmitReceipt|Promise<SubmitReceipt>}};
export type JsonSummary = {rootKind:JsonKind;nodeCount:number;keyCount:number;stringCount:number;numberCount:number;maxDepth:number;inputUtf16Units:number};
export type JsonAnalysis = {tokens:string[];summary:JsonSummary};
export type JsonInspect = {status:'inspected';inputSubmitted:false}&JsonSummary;
export type JsonReady = {done:false;mode:'send'|'choose-send';outputs:Partial<Record<Format,string>>;summary:JsonSummary;format:Format|undefined};
export type JsonPrepared = {done:true;value:JsonInspect}|JsonReady;
export type JsonSubmitted = {status:'submitted';format:Format;outputUtf16Units:number;inputSubmitted:true}&JsonSummary;
export type JsonCancelled = {status:'cancelled';inputSubmitted:false}&JsonSummary;
export type JsonInput = {mode:'inspect'|'choose-send';text:string}|{mode:'send';text:string;format:Format};
export type SelectionInput = {mode:'inspect'|'send';text:string;path:readonly(string|number)[];format:Format};
export type SelectionNode = {start:number;end:number;count:number;kind:JsonKind;children?:Map<string,SelectionNode>|SelectionNode[]};
export type SelectionSummary = {selectedKind:JsonKind;selectedNodeCount:number;pathLength:number;inputUtf16Units:number;outputUtf16Units:number};
export type SelectionTask = {mode:'inspect'|'send';text:string;summary:SelectionSummary};
export type SelectionInspect = {status:'inspected';inputSubmitted:false}&SelectionSummary;
export type SelectionSubmitted = {status:'submitted';inputSubmitted:true}&SelectionSummary;
export type FormatActionResult = JsonInspect|JsonSubmitted|JsonCancelled;
export type SelectionActionResult = SelectionInspect|SelectionSubmitted;
export type JsonActionResult = FormatActionResult|SelectionActionResult;
